examples.template:
Row(
    horizontalArrangement = Arrangement.spacedBy(MonarchTheme.spacing.space3),
    verticalAlignment = Alignment.CenterVertically,
) {
    MonarchButton(
        text = if (recording) {{stop}} else {{start}},
        onClick = { recording = !recording },
        size = MonarchButtonSize.Sm,
    )
    MonarchRecordingIndicator(recording = recording, elapsedMillis = {{elapsedMillis}})
}

examples.code:
Row(
    horizontalArrangement = Arrangement.spacedBy(MonarchTheme.spacing.space3),
    verticalAlignment = Alignment.CenterVertically,
) {
    MonarchButton(
        text = if (recording) "Stop recording" else "Start recording",
        onClick = { recording = !recording },
        size = MonarchButtonSize.Sm,
    )
    MonarchRecordingIndicator(recording = recording, elapsedMillis = 83_000)
}
